import { Vec3, Quat } from '../physics/math.js';

/**
 * Anthropometric model of an adult male (1.78 m, ~74.5 kg). Bind pose = relaxed anatomical stance:
 * facing +Z, left side toward +X, arms hanging with 12 deg abduction, palms facing the thighs.
 * Segment masses follow de Leva (1996); joint ranges of motion follow standard clinical ROM tables.
 * Everything is defined for the left side and the midline; the right side is generated by mirroring.
 */

const D2R = Math.PI / 180;
const ARM_ABD = 12 * D2R;
const sinA = Math.sin(ARM_ABD), cosA = Math.cos(ARM_ABD);

export const LANDMARKS = {
  hipL: new Vec3(0.088, 0.925, 0.0),
  kneeL: new Vec3(0.097, 0.505, 0.006),
  ankleL: new Vec3(0.105, 0.085, -0.02),
  lumbar: new Vec3(0, 1.035, -0.045),
  thoracic: new Vec3(0, 1.195, -0.055),
  neckBase: new Vec3(0, 1.475, -0.05),
  neckTop: new Vec3(0, 1.595, -0.02),
  shoulderL: new Vec3(0.18, 1.43, -0.035),
};
LANDMARKS.elbowL = new Vec3(0.18 + 0.3 * sinA, 1.43 - 0.3 * cosA, -0.045);
LANDMARKS.wristL = new Vec3(LANDMARKS.elbowL.x + 0.255 * sinA, LANDMARKS.elbowL.y - 0.255 * cosA, -0.032);

const UP = new Vec3(0, 1, 0);
const FWD = new Vec3(0, 0, 1);
const LAT = new Vec3(1, 0, 0); // toward the character's left

// Quaternion of a right-handed frame given its Y axis and a hint for the X axis.
export function frameFromXY(xHint, y) {
  const Y = y.clone().normalize();
  const X = xHint.clone().addScaled(Y, -xHint.dot(Y)).normalize();
  const Z = new Vec3().crossVectors(X, Y);
  return new Quat().setFromBasis(X, Y, Z);
}

// Frame given its Y axis and a hint for the Z axis.
export function frameFromYZ(y, zHint) {
  const Y = y.clone().normalize();
  const Z = zHint.clone().addScaled(Y, -zHint.dot(Y)).normalize();
  const X = new Vec3().crossVectors(Y, Z);
  return new Quat().setFromBasis(X, Y, Z);
}

const dir = (a, b) => new Vec3().subVectors(b, a).normalize();

const upperArmDirL = dir(LANDMARKS.shoulderL, LANDMARKS.elbowL);
const forearmDirL = dir(LANDMARKS.elbowL, LANDMARKS.wristL);
const thighDirL = dir(LANDMARKS.hipL, LANDMARKS.kneeL);
const shinDirL = dir(LANDMARKS.kneeL, LANDMARKS.ankleL);
const elbowAxisL = new Vec3().crossVectors(FWD, upperArmDirL).normalize();
const shoulderCenterL = new Vec3(0.6, -0.45, 0.62).normalize();

