// Joints of the right side mirror the left: frame axes are reflected (x -> -x) with X negated to stay
// right-handed, so twist and swingZ ranges flip sign and swingX ranges are kept.
export function mirrorVec(v) {
  return new Vec3(-v.x, v.y, v.z);
}

export function mirrorFrame(q) {
  const X = new Vec3(1, 0, 0).applyQuat(q);
  const Y = new Vec3(0, 1, 0).applyQuat(q);
  const Z = new Vec3(0, 0, 1).applyQuat(q);
  const X2 = mirrorVec(X).negate();
  const Y2 = mirrorVec(Y);
  const Z2 = mirrorVec(Z);
  return new Quat().setFromBasis(X2, Y2, Z2);
}

export function mirrorLimits(L) {
  return {
    mode: L.mode,
    swingX: [L.swingX[0], L.swingX[1]],
    swingZ: [-L.swingZ[1], -L.swingZ[0]],
    twist: [-L.twist[1], -L.twist[0]],
  };
}

export function landmark(name) {
  if (LANDMARKS[name]) return LANDMARKS[name].clone();
  if (name.endsWith('R')) {
    const l = LANDMARKS[name.slice(0, -1) + 'L'];
    if (l) return mirrorVec(l);
  }
  throw new Error(`unknown landmark ${name}`);
}

function mirrorName(n) {
  return n.endsWith('L') ? n.slice(0, -1) + 'R' : n;
}

function mirrorShape(s) {
  const out = { ...s };
  if (Array.isArray(s.center)) out.center = [-s.center[0], s.center[1], s.center[2]];
  if (typeof s.a === 'string') out.a = mirrorName(s.a);
  else if (Array.isArray(s.a)) out.a = [-s.a[0], s.a[1], s.a[2]];
  if (typeof s.b === 'string') out.b = mirrorName(s.b);
  else if (Array.isArray(s.b)) out.b = [-s.b[0], s.b[1], s.b[2]];
  return out;
}

// Full list of segments (both sides), in parent-before-child order.
export function buildSegmentList() {
  const list = [];
  for (const def of SEGMENT_DEFS) {
    list.push({ ...def, side: def.name.endsWith('L') ? 'L' : 'C' });
  }
  for (const def of SEGMENT_DEFS) {
    if (!def.name.endsWith('L')) continue;
    const m = {
      ...def,
      name: mirrorName(def.name),
      parent: mirrorName(def.parent),
      joint: mirrorName(def.joint),
      side: 'R',
      shapes: def.shapes.map(mirrorShape),
      bone: def.bone ? { ...def.bone, from: mirrorName(def.bone.from), to: mirrorName(def.bone.to) } : undefined,
    };
    list.push(m);
  }
  // order: parents first
  const ordered = [];
  const added = new Set();
  while (ordered.length < list.length) {
    for (const s of list) {
      if (added.has(s.name)) continue;
      if (!s.parent || added.has(s.parent)) {
        ordered.push(s);
        added.add(s.name);
      }
    }
  }
  return ordered;
}

export function jointDef(name) {
  if (JOINT_DEFS[name]) return { ...JOINT_DEFS[name], name, side: name.endsWith('L') ? 'L' : 'C' };
  const left = JOINT_DEFS[name.slice(0, -1) + 'L'];
  if (!left) throw new Error(`unknown joint ${name}`);
  const def = {
    ...left,
    name,
    side: 'R',
    frame: mirrorFrame(left.frame),
    limits: mirrorLimits(left.limits),
  };
  if (left.centerDir) def.centerDir = mirrorVec(left.centerDir);
  if (left.boneDir) def.boneDir = mirrorVec(left.boneDir);
  return def;
}

export const TOTAL_MASS = SEGMENT_DEFS.reduce((s, d) => s + d.mass * (d.name.endsWith('L') ? 2 : 1), 0);

export const DIRS = { UP, FWD, LAT, upperArmDirL, forearmDirL, thighDirL, shinDirL };
